parameters.query:
with d as (
  insert into documents (file_name, file_hash, source, status, status_reason)
  values ($1, $2, 'folder', 'received', 'Intake OK, text extracted')
  returning id, file_name, status, received_at
), e_intake as (
  insert into processing_events (document_id, stage, outcome, detail)
  select id, 'intake', 'ok', jsonb_build_object('file_name', file_name) from d
), e_read as (
  insert into processing_events (document_id, stage, outcome, detail)
  select id, 'read', 'ok', jsonb_build_object('text_length', length($3::text)) from d
)
select * from d;

